21	    #[must_use]
22	    pub fn union(self, other: Self) -> Self {
23	        match (self, other) {
24	            (Self::TypeError, _) | (_, Self::TypeError) => Self::TypeError,
25	            (Self::Unknown, _) | (_, Self::Unknown) => Self::Unknown,
26	            (Self::Atom(a), Self::Atom(b)) => {
27	                if a.is_subtype_of(b) {
